import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Entra ID Inventory Modules","description":"Complete catalog of AzureScout Microsoft Entra ID inventory modules.","frontmatter":{"description":"Complete catalog of AzureScout Microsoft Entra ID inventory modules."},"headers":[],"relativePath":"entra-modules.md","filePath":"entra-modules.md"}'),d={name:"entra-modules.md"};function o(n,e,r,l,c,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="entra-id-inventory-modules" tabindex="-1">Entra ID Inventory Modules <a class="header-anchor" href="#entra-id-inventory-modules" aria-label="Permalink to &quot;Entra ID Inventory Modules&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>AzureScout includes <strong>17 Entra ID (Identity) inventory modules</strong> that extract tenant-wide identity and access management data via the Microsoft Graph API. They live alongside one ARM-based module (<code>ManagedIds</code> — user-assigned managed identity <em>resources</em>, as opposed to the Entra-side <code>ManagedIdentities</code> service-principal view below) in the <code>Identity</code> category folder — see <a href="./arm-modules.html#identity-1-arm-module">ARM Modules: Identity</a> for that one.</p><p>Run Entra-only extraction with:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope EntraOnly</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="how-entra-extraction-works" tabindex="-1">How Entra Extraction Works <a class="header-anchor" href="#how-entra-extraction-works" aria-label="Permalink to &quot;How Entra Extraction Works&quot;">​</a></h2><p>The <code>Start-AZSCEntraExtraction</code> function calls <code>Invoke-AZSCGraphRequest</code> for each Entra module, which:</p><ol><li>Authenticates via the Graph token obtained during login</li><li>Queries the relevant Microsoft Graph endpoint</li><li>Handles pagination (following <code>@odata.nextLink</code>)</li><li>Normalizes each result into a consistent resource shape:</li></ol><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Display Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;TYPE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;microsoft.graph/users&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tenantId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00000000-...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;properties&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="module-catalog" tabindex="-1">Module Catalog <a class="header-anchor" href="#module-catalog" aria-label="Permalink to &quot;Module Catalog&quot;">​</a></h2><p><code>Get-ScoutEntraQueryCatalog</code> (<code>src/collect/Get-ScoutEntraQueryCatalog.ps1</code>) is the single source of truth for these 17 queries — <code>Start-AZSCEntraExtraction</code> runs exactly this list, and the <code>-PermissionAudit</code> impact table is built by joining the same list against the collector manifests, so the two can no longer drift the way a hand-maintained second copy could.</p><table tabindex="0"><thead><tr><th>Module</th><th>Graph Endpoint</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td>Users</td><td><code>/users</code></td><td><code>User.Read.All</code></td><td>All user accounts (members and guests)</td></tr><tr><td>Groups</td><td><code>/groups</code></td><td><code>Group.Read.All</code></td><td>Security groups, Microsoft 365 groups, distribution lists</td></tr><tr><td>Applications</td><td><code>/applications</code></td><td><code>Application.Read.All</code></td><td>Application registrations (app IDs, credentials, API permissions)</td></tr><tr><td>Service Principals</td><td><code>/servicePrincipals</code></td><td><code>Application.Read.All</code></td><td>Enterprise applications and service principals</td></tr><tr><td>Managed Identities</td><td><code>/servicePrincipals</code> (filtered to <code>servicePrincipalType eq &#39;ManagedIdentity&#39;</code>)</td><td><code>Application.Read.All</code></td><td>Managed identities (system and user-assigned), as seen from the Entra service-principal object</td></tr><tr><td>Directory Roles</td><td><code>/directoryRoles</code></td><td><code>RoleManagement.Read.Directory</code></td><td>Activated directory roles and their members</td></tr><tr><td>PIM Assignments</td><td><code>/roleManagement/directory/roleAssignments</code></td><td><code>RoleManagement.Read.Directory</code></td><td>Privileged Identity Management (PIM) role assignments</td></tr><tr><td>Conditional Access Policies</td><td><code>/identity/conditionalAccess/policies</code></td><td><code>Policy.Read.All</code></td><td>Conditional Access policies</td></tr><tr><td>Named Locations</td><td><code>/identity/conditionalAccess/namedLocations</code></td><td><code>Policy.Read.All</code></td><td>Trusted locations for conditional access</td></tr><tr><td>Administrative Units</td><td><code>/directory/administrativeUnits</code></td><td><code>AdministrativeUnit.Read.All</code></td><td>Administrative units for delegated management</td></tr><tr><td>Domains</td><td><code>/domains</code></td><td><code>Domain.Read.All</code></td><td>Verified and unverified domains</td></tr><tr><td>Subscribed SKUs</td><td><code>/subscribedSkus</code></td><td><code>Organization.Read.All</code></td><td>License SKUs and service plan assignments</td></tr><tr><td>Cross-Tenant Access</td><td><code>/policies/crossTenantAccessPolicy/partners</code></td><td><code>Policy.Read.All</code></td><td>B2B cross-tenant access settings</td></tr><tr><td>Security Policies</td><td><code>/policies/authorizationPolicy</code></td><td><code>Policy.Read.All</code></td><td>Tenant authorization policy</td></tr><tr><td>Risky Users</td><td><code>/identityProtection/riskyUsers</code></td><td><code>IdentityRiskyUser.Read.All</code></td><td>Users flagged by Identity Protection (requires Entra ID P2)</td></tr><tr><td>Identity Providers ⚠️</td><td><code>/identity/identityProviders</code></td><td><code>IdentityProvider.Read.All</code></td><td>Configured external/social identity providers</td></tr><tr><td>Security Defaults ⚠️</td><td><code>/policies/identitySecurityDefaultsEnforcementPolicy</code></td><td><code>Policy.Read.All</code></td><td>Tenant-wide security defaults enforcement state</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Collected, normalized, and read by nothing</p><p><code>Identity Providers</code> and <code>Security Defaults</code> are queried and land in <code>EntraResources</code> like every other row here, but no collector consumes either <code>entra/identityproviders</code> or <code>entra/securitydefaults</code> type. The catalog keeps them rather than dropping them so the <code>-PermissionAudit</code> impact table can say so explicitly — a permission Scout asks for and does not need belongs in the report, not in a comment nobody reads. <code>AuditLog.Read.All</code> used to be requested with the same problem (no collector ever consumed <code>auditLogs/*</code>); it has been removed from the ask entirely rather than kept as a fourth unconsumed entry.</p></div><h2 id="required-microsoft-graph-permissions" tabindex="-1">Required Microsoft Graph Permissions <a class="header-anchor" href="#required-microsoft-graph-permissions" aria-label="Permalink to &quot;Required Microsoft Graph Permissions&quot;">​</a></h2><blockquote><p><strong>&quot;I&#39;m a Global Administrator but the Entra modules still fail with 403 — why?&quot;</strong></p><p><strong>Global Administrator is an Entra directory <em>role</em>, not a Microsoft Graph API <em>scope</em>.</strong> Entra extraction uses the Graph token that <strong>Azure CLI</strong> issues (<code>az account get-access-token --resource https://graph.microsoft.com</code>). That token only carries the <strong>delegated Graph scopes the Azure CLI application has been consented</strong> for you — your directory role does <strong>not</strong> widen those scopes. So an endpoint whose scope has not been consented returns <code>403 Forbidden</code> regardless of your role.</p></blockquote><p>To read every module above, the signed-in identity needs these <strong>delegated</strong> Microsoft Graph permissions consented for the Azure CLI app (or your own app if you authenticate with one) — see the Permission column in the <a href="#module-catalog">Module Catalog</a> above for which permission unlocks which module:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Unlocks</th></tr></thead><tbody><tr><td><code>User.Read.All</code></td><td>Users</td></tr><tr><td><code>Group.Read.All</code></td><td>Groups</td></tr><tr><td><code>Application.Read.All</code></td><td>Applications, Service Principals, Managed Identities</td></tr><tr><td><code>RoleManagement.Read.Directory</code></td><td>Directory Roles, PIM Assignments</td></tr><tr><td><code>Policy.Read.All</code></td><td>Conditional Access Policies, Named Locations, Security Policies, Cross-Tenant Access, Security Defaults ⚠️</td></tr><tr><td><code>AdministrativeUnit.Read.All</code></td><td>Administrative Units</td></tr><tr><td><code>Domain.Read.All</code></td><td>Domains</td></tr><tr><td><code>Organization.Read.All</code></td><td>Subscribed SKUs</td></tr><tr><td><code>IdentityRiskyUser.Read.All</code></td><td>Risky Users (Identity Protection — also requires Entra ID P2)</td></tr><tr><td><code>IdentityProvider.Read.All</code> ⚠️</td><td>Identity Providers</td></tr></tbody></table><p>⚠️ marks the two permissions behind the unconsumed queries — granting them satisfies the pre-flight but adds nothing to any report; see the warning above.</p><p>A broad <code>Directory.Read.All</code> grant also satisfies <code>User.Read.All</code>, <code>Group.Read.All</code> and <code>Application.Read.All</code> in practice, since it is a superset scope, but the table above is the minimum each query actually needs.</p><p>Grant/consent once (tenant admin), e.g.:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Consent the Azure CLI app to the delegated scopes, then re-login:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">az login </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scope https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">graph.microsoft.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.default</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (Or have a Global Admin grant admin-consent for the scopes above in the Entra portal.)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Endpoints requiring a licensing tier you don&#39;t have (e.g. Risky Users without Entra ID P2) will still 403 — that is expected and is handled by <a href="#graceful-degradation">Graceful Degradation</a> below rather than aborting the run.</p><h2 id="data-normalization" tabindex="-1">Data Normalization <a class="header-anchor" href="#data-normalization" aria-label="Permalink to &quot;Data Normalization&quot;">​</a></h2><p>All 17 Entra modules produce output in the same normalized shape:</p><table tabindex="0"><thead><tr><th>Field</th><th>Source</th></tr></thead><tbody><tr><td><code>id</code></td><td>Graph object <code>id</code></td></tr><tr><td><code>name</code></td><td><code>displayName</code> (or most relevant name field)</td></tr><tr><td><code>TYPE</code></td><td>Synthetic type string (e.g., <code>microsoft.graph/users</code>)</td></tr><tr><td><code>tenantId</code></td><td>Tenant ID from the current session</td></tr><tr><td><code>properties</code></td><td>Full Graph object properties</td></tr></tbody></table><p>This normalization allows ARM and Entra resources to be processed by the same reporting pipeline.</p><h2 id="graceful-degradation" tabindex="-1">Graceful Degradation <a class="header-anchor" href="#graceful-degradation" aria-label="Permalink to &quot;Graceful Degradation&quot;">​</a></h2><p>If a single Entra query fails (e.g., insufficient permissions for Conditional Access policies), the module:</p><ul><li>Logs a warning</li><li>Continues with the remaining 16 queries</li><li>Returns partial results rather than failing entirely</li></ul><p>If <em>all</em> queries fail, the function returns an empty <code>EntraResources</code> collection.</p>`,30)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
